const defaults={gold:1200,shards:12,level:1,wins:0,progress:0,owned:['aya','ren','mika','oni','kitsune','knight'],team:['aya','ren','mika','oni','kitsune','knight'],cardLevels:{},cardStars:{},dupes:{},gachaPulls:0,dungeonWins:0,dungeonFloorUnlocked:1,dungeonFloorsCleared:[],bossMilestonesClaimed:[],claimed:[],favorites:[]};
let save;try{save={...defaults,...JSON.parse(localStorage.getItem('dmt_offline_save')||'{}')}}catch(e){save={...defaults}}
let fight=null; let dungeonMode='tower'; let dungeonFloor=1; let lastGacha=[];
save.dungeonFloorUnlocked=Math.max(1,Math.min(30,Number(save.dungeonFloorUnlocked||1)));save.dungeonFloorsCleared=Array.isArray(save.dungeonFloorsCleared)?save.dungeonFloorsCleared:[];save.bossMilestonesClaimed=Array.isArray(save.bossMilestonesClaimed)?save.bossMilestonesClaimed:[];if(save.dungeonFloorUnlocked===10&&save.dungeonFloorsCleared.includes(10))save.dungeonFloorUnlocked=11;
save.exp=Number(save.exp||0);save.team=Array.isArray(save.team)?save.team.filter((id,i,a)=>DB.some(c=>c.id===id)&&a.indexOf(id)===i).slice(0,6):[...defaults.team];if(!save.team.length)save.team=['aya'];save.owned=Array.isArray(save.owned)?save.owned: [...defaults.owned];save.favorites=Array.isArray(save.favorites)?save.favorites:[]; DB.forEach(c=>{if(!save.cardLevels[c.id])save.cardLevels[c.id]=1;if(!save.cardStars)save.cardStars={};if(!save.dupes)save.dupes={};if(!save.cardStars[c.id])save.cardStars[c.id]=1;if(!save.dupes[c.id])save.dupes[c.id]=0});
function persist(){localStorage.setItem('dmt_offline_save',JSON.stringify(save));updateHeader()}
function updateHeader(){document.getElementById('gold').textContent=save.gold;document.getElementById('shards').textContent=save.shards;document.getElementById('level').textContent=save.level;document.getElementById('wins').textContent=save.wins;document.getElementById('progress').textContent=`${save.wins} trận thắng · Dungeon ${save.dungeonFloorsCleared.length}/30 tầng`;  document.getElementById('power').textContent=teamPower();document.getElementById('teampower').textContent=teamPower();document.getElementById('teamcount').textContent=save.team.length}
function cardLevel(id){return Number(save.cardLevels?.[id]||1)}
function cardStars(id){return Math.min(6,Number(save.cardStars?.[id]||1))}
function starsHtml(id){let n=cardStars(id);return '<div class="starline">'+Array.from({length:6},(_,i)=>'<span class="'+(i<n?'lit':'')+'">★</span>').join('')+'</div>'}
function starClass(id){return 'star-'+cardStars(id)}
function statsFor(c){let lv=cardLevel(c.id);let st=cardStars(c.id);return {...c,level:lv,hp:Math.round((c.hp+(lv-1)*12)*(1+(st-1)*.08)),atk:Math.round((c.atk+(lv-1)*4)*(1+(st-1)*.08)),def:Math.round((c.def+(lv-1)*2)*(1+(st-1)*.05))}}
function teamPower(){return save.team.reduce((n,id)=>{let c=DB.find(x=>x.id===id);if(c)c=statsFor(c);return n+(c?c.atk*2+c.def+c.hp/5:0)},0)|0}
function enterGame(){show('home');if(!localStorage.getItem('dmt_tutorial_seen_v1'))openTutorial(false)}
function openChangelog(){const el=document.getElementById('changelogOverlay');if(el)el.classList.add('open')}
function closeChangelog(){const el=document.getElementById('changelogOverlay');if(el)el.classList.remove('open')}
function openTutorial(canDismiss=true){const el=document.getElementById('tutorialOverlay');if(!el)return;el.dataset.dismiss=canDismiss?'1':'0';document.getElementById('tutorialClose').hidden=!canDismiss;el.classList.add('open')}
function closeTutorial(enterHome=false){const el=document.getElementById('tutorialOverlay');if(el)el.classList.remove('open');localStorage.setItem('dmt_tutorial_seen_v1','1');if(enterHome)show('home')}
function show(id){document.body.classList.toggle('startup-active',id==='start');document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));document.getElementById(id).classList.add('active');if(id==='team')renderTeam();if(id==='cards')renderCollection();if(id==='upgrade')renderUpgrade();if(id==='ascend')renderAscend();if(id==='quests')renderQuests();if(id==='gacha')renderGacha();if(id==='dungeon')renderDungeon();if(id==='battle'&&(!fight||fight.ended))resetFight();window.scrollTo(0,0)}


const DEVIL_LORE={
 aya:{story:'Khi mặt trăng đỏ xuất hiện trên bầu trời thành phố, Lilith tỉnh giấc trong một nhà thờ đổ nát. Nàng từng canh giữ cánh cổng giữa mộng và thực, nhưng đã phá luật để cứu một linh hồn con người. Từ đó, tên nàng bị xóa khỏi mọi khế ước cổ.',personality:'Kiêu hãnh, điềm tĩnh và khó tin người. Lilith luôn tỏ ra lạnh lùng, nhưng âm thầm bảo vệ những ai dám đứng lên chống lại định mệnh.',quote:'“Đừng quỳ trước bóng tối. Hãy khiến nó học cách sợ ngươi.”'},
 asmodeus:{story:'Asmodeus là đóa hồng cuối cùng trong khu vườn bị phong ấn dưới lòng đất. Mỗi cánh hoa giữ một ký ức mà thế giới muốn quên. Nàng lang thang tìm người có thể nghe hết những ký ức ấy mà không đánh mất chính mình.',personality:'Duyên dáng, tinh nghịch và tinh tế. Nàng thích thử thách đối thủ bằng lời nói trước khi tung lời nguyền, nhưng rất trung thành với người đã được nàng công nhận.',quote:'“Mọi lời hứa đều có gai. Quan trọng là ngươi có dám nắm lấy đóa hồng không.”'},
 mika:{story:'Astaroth đọc được những đường nứt của thời gian trong ánh sao. Sau khi nhìn thấy một tương lai nơi Tokyo chìm dưới biển đen, cô đánh đổi ký ức của mình để giữ lại một con đường khác cho nhân loại.',personality:'Trầm lặng, thông tuệ và hay nói bằng ẩn dụ. Astaroth thường đứng ngoài cuộc tranh luận, nhưng quyết định của cô có thể xoay chuyển cả trận chiến.',quote:'“Tương lai không phải lời tiên tri. Nó là cánh cửa đang chờ một bàn tay mở ra.”'},
 ren:{story:'Lucifer từng là người giữ ngọn sao dẫn đường cho các linh hồn lạc lối. Khi thiên giới đóng cánh cổng cứu viện, anh tự bẻ gãy đôi cánh của mình và rơi xuống trần gian để tiếp tục lời thề.',personality:'Lý trí, nghiêm nghị và mang mặc cảm của kẻ từng thất bại. Anh không tìm sự tha thứ; anh muốn chứng minh rằng lòng trắc ẩn không phải điểm yếu.',quote:'“Nếu thiên đường quay lưng, ta sẽ tự thắp bình minh.”'},
 oni:{story:'Satan bị phong ấn trong lò rèn dưới lòng đất sau khi ngọn lửa của hắn thiêu rụi cả một đạo quân. Hắn không nhớ vì sao trận chiến bắt đầu, chỉ nhớ lời hứa sẽ không để ngọn lửa ấy chạm vào người vô tội lần nữa.',personality:'Nóng nảy, thẳng thắn và ghét sự phản bội. Dưới vẻ hung bạo là một chiến binh giữ lời hứa đến cùng.',quote:'“Ta không thể dập tắt địa ngục. Nhưng ta có thể chọn nơi ngọn lửa cháy.”'},
 kitsune:{story:'Leviathan ngủ dưới hồ gương nơi mọi bí mật đều hóa thành băng. Khi mặt hồ vỡ, linh hồn cổ đại thức dậy và đi tìm kẻ đã đánh cắp mùa đông khỏi thế giới.',personality:'Lạnh lùng, kiên nhẫn và quan sát sắc bén. Cô hiếm khi nổi giận; một khi đã ra tay, mọi chuyển động của đối thủ đều chậm lại như bị đóng băng.',quote:'“Im lặng đi. Ta muốn nghe khoảnh khắc số phận nứt vỡ.”'},
 knight:{story:'Metatron là người gác cổng của thư viện phán quyết, nơi ghi lại mọi lựa chọn từng bị con người chối bỏ. Khi cuốn sách cuối cùng bị xé, anh rời nhiệm sở để tìm kẻ đã sửa đổi lịch sử.',personality:'Kỷ luật, công bằng và cứng rắn. Anh tin rằng công lý cần lòng can đảm, không phải một chiếc ngai cao hơn người khác.',quote:'“Không ai đứng ngoài phán quyết của chính mình.”'},
 beelzebub:{story:'Beelzebub xuất hiện như một đàn bướm đen sau cơn mưa sao băng. Mỗi cánh bướm là một mảnh ý thức bị bỏ quên, hợp lại thành một thực thể vừa tò mò vừa đáng sợ.',personality:'Tò mò, nói chuyện như trẻ nhỏ và thay đổi chủ đề bất ngờ. Nhưng cô có thể nhận ra nỗi cô đơn mà người khác che giấu.',quote:'“Một mình là một tiếng nói. Chúng ta là cả một bản giao hưởng.”'},
 samael:{story:'Samael từng dẫn đường cho những linh hồn không thể siêu thoát. Một ngày, anh từ chối thu lấy linh hồn của người bạn cuối cùng và trở thành kẻ bị săn đuổi bởi chính bóng tối mình phục vụ.',personality:'Ít nói, sắc sảo và luôn giữ khoảng cách. Anh không hứa sẽ cứu ai, nhưng thường là người quay lại cuối cùng để kéo đồng đội khỏi vực sâu.',quote:'“Bóng tối không xóa được dấu chân. Nó chỉ giấu chúng khỏi người không muốn nhìn.”'},
 marbas:{story:'Marbas là nhà giả kim của khu phố bị bỏ hoang, nơi mọi thứ đều nhiễm một loại sương độc kỳ lạ. Ông nghiên cứu chất độc không phải để hủy diệt, mà để tìm phương thuốc cho những người đã biến đổi.',personality:'Thực dụng, châm biếm và tò mò quá mức. Ông xem mọi thất bại là dữ liệu, kể cả những sai lầm của chính mình.',quote:'“Độc dược và thuốc chữa chỉ khác nhau ở liều lượng… và ý định.”'},
 forneus:{story:'Forneus thức tỉnh trong khu vườn mọc xuyên qua bê tông. Linh hồn của cô gắn với những mầm cây cuối cùng còn sống ở Tokyo, và mỗi bước chân đều khiến một ký ức về thiên nhiên trở lại.',personality:'Dịu dàng, bền bỉ và không dễ khuất phục. Cô tin rằng những điều nhỏ bé vẫn có thể sống sót sau tận thế.',quote:'“Một chiếc lá mọc lên cũng là lời phản đối của thế giới.”'},
 valak:{story:'Valak từng là kiếm sĩ canh giữ tuyến tàu điện đêm. Khi sấm sét xé toạc đường hầm, thanh kiếm của anh hấp thụ tiếng vang của cơn bão và biến anh thành lưỡi kiếm cuối cùng giữa hai cõi.',personality:'Nhanh nhẹn, bộc trực và thích hành động hơn lời nói. Anh luôn chọn đứng ở tuyến đầu để đồng đội có thời gian chuẩn bị.',quote:'“Nếu sấm sét đã gọi tên ta, ta sẽ trả lời bằng lưỡi kiếm.”'}
};

const STAR_ART_PREFIX={aya:'lilith',mika:'astaroth',asmodeus:'asmodeus'};
function cardImagePath(c,lowestStar=false){const prefix=STAR_ART_PREFIX[c.id],n=lowestStar?1:cardStars(c.id);if(prefix)return `assets/cards/${prefix}_${n}star.webp?v=0166`;return `assets/cards/${c.image||c.id+'.webp'}`}
function cardFallbackPath(c){return c.id==='aya'?'assets/cards/lilith_ssr.webp?v=0120':`assets/cards/${c.image||c.id+'.webp'}?v=0120`}
function artHtml(c,extraClass='',lowestStar=false){const src=cardImagePath(c,lowestStar),base=cardFallbackPath(c);return `<div class="art ${starClass(c.id)} ${extraClass}" data-card="${c.id}"><img class="card-portrait" src="${src}" alt="${c.name}" loading="lazy" onerror="if(this.dataset.fallback!=='1'&&this.src!==new URL('${base}',location.href).href){this.dataset.fallback='1';this.src='${base}'}else{this.style.display='none';this.parentElement.classList.remove('has-image')}" onload="this.parentElement.classList.add('has-image')"><span class="art-fallback">${c.art}</span><span class="rarity-badge ${c.rarity}" aria-label="Độ hiếm ${c.rarity}">${c.rarity}</span></div>`}
function cardHtml(base,buttonText,onclick,selected=false){let c=statsFor(base);return `<article class="card ${selected?'selected':''}"><div>${artHtml(c)}${starsHtml(c.id)}<div class="rarity ${c.rarity}">${c.rarity} · ★${cardStars(c.id)} · Lv.${c.level}</div><h3>${c.name}</h3><p>${c.desc}<br>HP ${c.hp} · ATK ${c.atk} · DEF ${c.def}</p></div><button onclick="${onclick}">${buttonText}</button></article>`}
function renderTeam(){document.getElementById('teamcards').innerHTML=DB.filter(c=>save.owned.includes(c.id)).map(c=>cardHtml(c,save.team.includes(c.id)?'✓ Đang chọn':'＋ Thêm',`toggleTeam('${c.id}')`,save.team.includes(c.id))).join('');const slots=document.getElementById('teamSlots');if(slots)slots.innerHTML=Array.from({length:6},(_,i)=>{const id=save.team[i],c=DB.find(x=>x.id===id);return `<div class="team-slot ${c?'filled':''}"><span>VỊ TRÍ ${i+1}</span><b>${c?c.name.split(' · ')[0]:'Trống'}</b></div>`}).join('');updateHeader()}
function toggleTeam(id){if(save.team.includes(id)){if(save.team.length===1){alert('Đội hình cần ít nhất 1 thẻ.');return}save.team=save.team.filter(x=>x!==id)}else{if(save.team.length>=6){alert('Đội hình đã đủ 6 Devil. Bỏ chọn một thẻ trước.');return}save.team.push(id)}persist();renderTeam()}
function renderCollection(){
 let q=(document.getElementById('cardSearch')?.value||'').trim().toLowerCase(),r=document.getElementById('rarityFilter')?.value||'all',sort=document.getElementById('cardSort')?.value||'rarity',scope=document.getElementById('collectionScope')?.value||'owned';
 const ownedCount=DB.filter(c=>save.owned.includes(c.id)).length;
 let list=DB.filter(c=>{const owned=save.owned.includes(c.id),fav=save.favorites.includes(c.id),team=save.team.includes(c.id);const scopeOK=scope==='all'||(scope==='owned'&&owned)||(scope==='unowned'&&!owned)||(scope==='favorites'&&fav)||(scope==='team'&&team);return scopeOK&&(!q||(c.name+' '+c.skill+' '+c.desc+' '+c.rarity).toLowerCase().includes(q))&&(r==='all'||c.rarity===r)});
 let rank={SSR:3,SR:2,R:1};
 list.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='atk'?statsFor(b).atk-statsFor(a).atk:sort==='hp'?statsFor(b).hp-statsFor(a).hp:sort==='level'?cardLevel(b.id)-cardLevel(a.id):sort==='stars'?cardStars(b.id)-cardStars(a.id):sort==='favorites'?(Number(save.favorites.includes(b.id))-Number(save.favorites.includes(a.id)))||rank[b.rarity]-rank[a.rarity]:sort==='power'?(statsFor(b).atk*2+statsFor(b).def+statsFor(b).hp/5)-(statsFor(a).atk*2+statsFor(a).def+statsFor(a).hp/5):rank[b.rarity]-rank[a.rarity]);
 const ssr=save.owned.filter(id=>DB.some(c=>c.id===id&&c.rarity==='SSR')).length,sr=save.owned.filter(id=>DB.some(c=>c.id===id&&c.rarity==='SR')).length,rr=save.owned.filter(id=>DB.some(c=>c.id===id&&c.rarity==='R')).length;
 document.getElementById('collectionCount').innerHTML=`<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px"><span class="pill">Sở hữu ${ownedCount}/${DB.length}</span><span class="pill">SSR ${ssr}</span><span class="pill">SR ${sr}</span><span class="pill">R ${rr}</span><span class="pill">♥ ${save.favorites.length} yêu thích</span><span class="pill">Đội hình ${save.team.length}/6</span></div>Hiển thị ${list.length} Devil · ${scope==='owned'?'đã sở hữu':scope==='unowned'?'chưa sở hữu':scope==='favorites'?'yêu thích':scope==='team'?'đang trong đội':'toàn bộ danh mục'}`;
 document.getElementById('collection').innerHTML=list.map(c=>{let owned=save.owned.includes(c.id),st=statsFor(c),fav=save.favorites.includes(c.id),inTeam=save.team.includes(c.id);return `<article class="card collection-card ${owned?'':'locked'} ${inTeam?'selected':''}" onclick="openDevilDetail('${c.id}')"><div>${artHtml(c)}${starsHtml(c.id)}<div class="rarity ${c.rarity}">${owned?c.rarity+' · ★'+cardStars(c.id)+' · Lv.'+cardLevel(c.id):'CHƯA SỞ HỮU · '+c.rarity}</div><h3>${c.name} ${fav?'♥':''} ${inTeam?'<span class="pill">Đội hình</span>':''}</h3><p>${c.skill}<br>${owned?`HP ${st.hp} · ATK ${st.atk} · DEF ${st.def}`:'Mở chi tiết để xem hồ sơ'}</p></div><div style="display:flex;gap:6px"><button style="flex:1" onclick="event.stopPropagation();openDevilDetail('${c.id}')">${owned?'Chi tiết':'Hồ sơ'}</button><button title="${fav?'Bỏ yêu thích':'Thêm yêu thích'}" aria-label="${fav?'Bỏ yêu thích':'Thêm yêu thích'}" onclick="event.stopPropagation();toggleFavoriteFromCollection('${c.id}')">${fav?'♥':'♡'}</button></div></article>`}).join('')||'<div class="panel muted">Không tìm thấy thẻ phù hợp.</div>';
}
function toggleFavoriteFromCollection(id){save.favorites=Array.isArray(save.favorites)?save.favorites:[];save.favorites=save.favorites.includes(id)?save.favorites.filter(x=>x!==id):[...save.favorites,id];persist();renderCollection()}

let detailDevilId=null,detailPreviewStar=1;
function openDevilDetail(id){const c=DB.find(x=>x.id===id);if(!c)return;detailDevilId=id;detailPreviewStar=cardStars(id);renderDevilDetail();document.getElementById('devilDetail').classList.add('open');document.body.style.overflow='hidden'}
function closeDevilDetail(){document.getElementById('devilDetail').classList.remove('open');document.body.style.overflow='';detailDevilId=null;renderCollection()}
function renderDevilDetail(){const c=DB.find(x=>x.id===detailDevilId);if(!c)return;const owned=save.owned.includes(c.id),st=statsFor(c),fav=save.favorites.includes(c.id),prefix=STAR_ART_PREFIX[c.id];let image=prefix?`assets/cards/${prefix}_${detailPreviewStar}star.webp?v=0160`:`assets/cards/${c.image||c.id+'.webp'}?v=0160`;let fallback=cardFallbackPath(c);document.getElementById('devilDetailBody').innerHTML=`<div class="detail-grid"><div><div class="art ${starClass(c.id)} ${prefix?'':'detail-static-art'}"><img class="card-portrait" src="${image}" alt="${c.name}" onerror="if(this.dataset.fallback!=='1'){this.dataset.fallback='1';this.src='${fallback}'}else{this.style.display='none';this.parentElement.classList.remove('has-image')}" onload="this.parentElement.classList.add('has-image')"><span class="art-fallback">${c.art}</span><span class="rarity-badge ${c.rarity}" aria-label="Độ hiếm ${c.rarity}">${c.rarity}</span></div>${prefix?`<div class="evo-buttons" aria-label="Xem ảnh tiến hóa">${[1,2,3,4,5,6].map(n=>`<button class="${n===detailPreviewStar?'primary':''}" onclick="setDetailStar(${n})">★${n}</button>`).join('')}</div><p class="muted" style="font-size:11px;text-align:center">Xem ảnh tiến hóa · không thay đổi sao thực tế</p>`:''}</div><div><div class="rarity ${c.rarity}">${c.rarity} · ${owned?'ĐÃ SỞ HỮU':'CHƯA SỞ HỮU'}</div><h2 class="detail-title">${c.name}</h2><p class="muted">${c.desc}</p><div class="lore-box"><div class="kicker">HỒ SƠ TRUYỀN THUYẾT</div><p><b>Tiểu sử</b><br>${(DEVIL_LORE[c.id]||{story:`${c.name.split(' · ')[0]} xuất hiện khi ranh giới giữa hai thế giới bắt đầu rạn nứt. Linh hồn này đang tìm một khế ước đủ mạnh để thay đổi số phận của Tokyo.`}).story}</p><p><b>Tính cách</b><br>${(DEVIL_LORE[c.id]||{personality:'Bí ẩn, khó đoán và chỉ bộc lộ sức mạnh thật khi khế ước được thử thách.'}).personality}</p><blockquote>${(DEVIL_LORE[c.id]||{quote:'“Mọi khế ước đều bắt đầu bằng một lựa chọn.”'}).quote}</blockquote><small>Truyền thuyết fan-made cho bản phục dựng Devil Rocker.</small></div><div class="detail-statgrid"><div class="detail-stat"><b>${owned?st.hp:'—'}</b><small>HP</small></div><div class="detail-stat"><b>${owned?st.atk:'—'}</b><small>ATK</small></div><div class="detail-stat"><b>${owned?st.def:'—'}</b><small>DEF</small></div></div><div class="panel"><div class="row"><span>Kỹ năng</span><b>${c.skill}</b></div><p class="muted" style="font-size:12px">Hồ sơ và chỉ số thuộc bản phục dựng ; các thông số này là dữ liệu mô phỏng, không khẳng định trùng khớp máy chủ gốc.</p>${owned?`<div class="row"><span>Cấp độ</span><b>Lv.${cardLevel(c.id)}</b></div><div class="row"><span>Nâng sao</span><b>★${cardStars(c.id)}/6</b></div><div class="row"><span>Bản sao quy đổi</span><b>${save.dupes[c.id]||0}</b></div>`:'<p class="muted">Devil này chưa có trong bộ sưu tập của bạn.</p>'}</div>${owned?(()=>{const stars=cardStars(c.id),need=stars*(c.rarity==='SSR'?10:c.rarity==='SR'?6:3),next=stars<6?{...c,hp:Math.round(st.hp*1.08),atk:Math.round(st.atk*1.08),def:Math.round(st.def*1.05)}:st;return `<div class="panel" style="margin-top:10px;border-color:#77613d;background:linear-gradient(135deg,rgba(99,68,28,.18),rgba(16,18,34,.9))"><div class="kicker">DEVIL ASCENSION</div><h3 style="margin:6px 0">★ Nâng sao trực tiếp</h3><div class="row"><span>Chi phí lên ★${Math.min(6,stars+1)}</span><b>${stars>=6?'Đã tối đa':need+' mảnh'}</b></div><div class="row"><span>Mảnh hiện có</span><b>${save.shards||0}</b></div>${stars<6?`<p class="muted" style="font-size:12px">Sau nâng: HP ${next.hp} · ATK ${next.atk} · DEF ${next.def}</p>`:'<p class="muted">Devil đã đạt cấp sao tối đa.</p>'}<button class="primary" style="width:100%;margin-top:8px" onclick="detailAscend('${c.id}')" ${stars>=6||(save.shards||0)<need?'disabled':''}>${stars>=6?'Đã đạt ★6':(save.shards||0)<need?'Thiếu mảnh để nâng sao':`Nâng lên ★${stars+1} · ${need} mảnh`}</button><p class="muted" style="font-size:11px;margin-bottom:0">Mỗi sao: HP/ATK +8%, DEF +5% (mô phỏng ).</p></div>`})():''}<div class="actions"><button class="${fav?'favorite':''}" onclick="toggleFavorite('${c.id}')">${fav?'♥ Đã yêu thích':'♡ Thêm yêu thích'}</button>${owned?`<button onclick="detailToggleTeam('${c.id}')">${save.team.includes(c.id)?'✓ Đang trong đội':'＋ Thêm vào đội'}</button>`:''}<button onclick="closeDevilDetail()">Quay lại bộ sưu tập</button></div></div></div>`}
function detailAscend(id){const c=DB.find(x=>x.id===id);if(!c||!save.owned.includes(id))return;const stars=cardStars(id),need=stars*(c.rarity==='SSR'?10:c.rarity==='SR'?6:3);if(stars>=6){alert('Devil đã đạt tối đa 6 sao.');return}if((save.shards||0)<need){alert(`Chưa đủ mảnh. Cần ${need} mảnh để lên ★${stars+1}.`);return}if(!confirm(`Thăng ${c.name} từ ★${stars} lên ★${stars+1} với ${need} mảnh?`))return;save.shards-=need;save.cardStars[id]=stars+1;detailPreviewStar=stars+1;persist();renderDevilDetail();renderCollection();renderTeam();renderAscend();renderUpgrade();if(fight&&!fight.ended)renderBattle();updateHeader();} 
function setDetailStar(n){if(!detailDevilId||!STAR_ART_PREFIX[detailDevilId])return;detailPreviewStar=Math.max(1,Math.min(6,Number(n)||1));renderDevilDetail()}
function toggleFavorite(id){save.favorites=Array.isArray(save.favorites)?save.favorites:[];save.favorites=save.favorites.includes(id)?save.favorites.filter(x=>x!==id):[...save.favorites,id];persist();renderDevilDetail()}
function detailToggleTeam(id){if(save.team.includes(id)){if(save.team.length===1){alert('Đội hình cần ít nhất 1 Devil.');return}save.team=save.team.filter(x=>x!==id)}else{if(save.team.length>=6){alert('Đội hình giới hạn 6 Devil. Hãy bỏ chọn một thẻ trước.');return}if(!save.owned.includes(id))return;save.team.push(id)}persist();renderDevilDetail()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('devilDetail')?.classList.contains('open'))closeDevilDetail()});
function showSaveTools(){let el=document.getElementById('saveTools');el.hidden=!el.hidden;if(!el.hidden)document.getElementById('saveStatus').textContent='Tiến trình hiện lưu trong localStorage của trình duyệt này.'}
function exportSave(){let data={format:'devil-maker--save',version:1,exportedAt:new Date().toISOString(),save};let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='devil-maker-save-'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(url);document.getElementById('saveStatus').textContent='Đã tạo file sao lưu JSON.'}
function importSave(ev){let file=ev.target.files?.[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let data=JSON.parse(reader.result),candidate=data.save;if(data.format!=='devil-maker--save'||!candidate||!Array.isArray(candidate.owned)||!Array.isArray(candidate.team)||!Number.isFinite(candidate.gold)||!Number.isFinite(candidate.shards))throw new Error('Sai định dạng file sao lưu');candidate.owned=candidate.owned.filter(id=>DB.some(c=>c.id===id));candidate.team=candidate.team.filter(id=>candidate.owned.includes(id)).slice(0,6);if(!candidate.team.length)candidate.team=[candidate.owned[0]||DB[0].id];candidate.cardLevels=candidate.cardLevels||{};candidate.cardStars=candidate.cardStars||{};candidate.dupes=candidate.dupes||{};candidate.claimed=candidate.claimed||[];candidate.favorites=Array.isArray(candidate.favorites)?candidate.favorites:[];candidate.dungeonFloorUnlocked=Math.max(1,Math.min(30,Number(candidate.dungeonFloorUnlocked||1)));candidate.dungeonFloorsCleared=Array.isArray(candidate.dungeonFloorsCleared)?candidate.dungeonFloorsCleared:[];candidate.bossMilestonesClaimed=Array.isArray(candidate.bossMilestonesClaimed)?candidate.bossMilestonesClaimed:[];if(candidate.dungeonFloorUnlocked===10&&candidate.dungeonFloorsCleared.includes(10))candidate.dungeonFloorUnlocked=11;save={...defaults,...candidate};persist();document.getElementById('saveStatus').textContent='Khôi phục thành công. Tiến trình đã được lưu.';updateHeader();alert('Đã khôi phục tiến trình!')}catch(e){document.getElementById('saveStatus').textContent='Không nhập được: '+e.message}ev.target.value=''};reader.readAsText(file)}
const ENCOUNTERS={
 normal:[{name:'Oni lang thang',art:'👹',hp:180,atk:22,def:0},{name:'Ác linh canh cổng',art:'👺',hp:230,atk:26,def:2},{name:'BOSS · Quỷ tướng Huyết Nguyệt',art:'👿',hp:390,atk:32,def:4,boss:true}],
 hard:[{name:'Oni ga tàu',art:'👺',hp:290,atk:28,def:2},{name:'Kỵ sĩ vực sâu',art:'💀',hp:360,atk:32,def:4},{name:'BOSS · Kẻ nuốt linh hồn',art:'☠️',hp:560,atk:39,def:7,boss:true}],
 nightmare:[{name:'Ác linh vực nứt',art:'👿',hp:430,atk:34,def:4},{name:'Thợ săn bóng tối',art:'🦇',hp:520,atk:38,def:6},{name:'BOSS · Ma thần tận thế',art:'🐉',hp:780,atk:48,def:10,boss:true}]
};
let autoBattle=false,battleSpeed=1,autoTimer=null;
function floorEncounters(floor){const boss=floor%10===0;const area=Math.floor((floor-1)/10)+1;const localFloor=((floor-1)%10)+1;const areaNames=['Shinjuku Đổ Nát','Linh Giới Vỡ Nứt','Điện Quỷ Vương'];const areaName=areaNames[area-1];const localNames=['Ngõ Shinjuku','Ga tàu bỏ hoang','Đền vỡ','Khu phố đỏ','Hầm tàu ma','Rừng linh giới','Tháp bóng tối','Vực nứt','Cầu linh hồn','Điện thủ lĩnh'];const floorName=localNames[localFloor-1];const scale=1+(floor-1)*0.105;return [{name:`${areaName} · ${floorName} · Ác linh canh đường`,art:['👹','👺','🦇','💀'][floor%4],hp:Math.round(150*scale),atk:Math.round(19*scale),def:Math.floor((floor-1)/3)},{name:`${areaName} · ${floorName} · Hộ vệ linh giới`,art:['👺','💀','👿','🕷️'][floor%4],hp:Math.round(205*scale),atk:Math.round(23*scale),def:Math.floor((floor-1)/2)},{name:`${boss?'BOSS KHU VỰC '+area+' · ':''}${['Quỷ tướng Huyết Nguyệt','Kẻ nuốt linh hồn','Thủ lĩnh vực nứt'][area-1]} · Tầng ${floor}`,art:boss?'🐉':'👿',hp:Math.round((boss?390:270)*scale),atk:Math.round((boss?32:26)*scale),def:Math.floor(floor/2),boss}]}
function currentEncounter(){if(dungeonMode==='tower')return floorEncounters(dungeonFloor)[fight.wave-1];return (ENCOUNTERS[dungeonMode]||ENCOUNTERS.normal)[fight.wave-1]}
function resetFight(){stopAuto();let encounters=dungeonMode==='tower'?floorEncounters(dungeonFloor):(ENCOUNTERS[dungeonMode]||ENCOUNTERS.normal);fight={wave:1,waves:encounters.length,enemy:encounters[0].hp,enemyMax:encounters[0].hp,turn:1,heroHp:{},guard:false,ended:false,skillCooldown:{},statuses:{},enemyStatuses:[],bossUsed:false,enemyIntent:null,exp:0,damageByHero:{},damageTotal:0};save.team.forEach(id=>{let c=statsFor(DB.find(x=>x.id===id));fight.heroHp[id]=c.hp;fight.skillCooldown[id]=0;fight.statuses[id]=[];fight.damageByHero[id]=0});setEncounterUI();document.getElementById('battlelog').innerHTML='<div>Đợt 1 xuất hiện! Đánh thường có thể chí mạng; kỹ năng gây hiệu ứng theo nhân vật.</div>';['attackbtn','skillbtn','guardbtn'].forEach(id=>document.getElementById(id).disabled=false);document.getElementById('nextbtn').hidden=true;renderBattle();updateAutoButton()}
function setEncounterUI(){let e=currentEncounter(),field=document.querySelector('.battlefield'),art=document.getElementById('enemyart'),name=document.getElementById('enemyname');name.textContent=e.name;art.textContent=e.art;art.classList.toggle('boss-art',!!e.boss);name.classList.toggle('boss-name',!!e.boss);field.classList.toggle('boss-fight',!!e.boss);document.getElementById('waveLabel').textContent=`${e.boss?'✦ BOSS KHU VỰC ✦':'ENEMY'} · WAVE ${fight.wave}/${fight.waves}`;document.getElementById('enemybar').style.background=e.boss?'linear-gradient(90deg,#c02e55,#ff7b86)':'';document.getElementById('battleReward').classList.remove('show');document.getElementById('battleStats').classList.remove('show');let intent=document.getElementById('enemyIntent');intent.hidden=true;intent.textContent='';fight.enemyIntent=null}
function renderBattle(){if(!fight)return;document.getElementById('enemyhptext').textContent=`${Math.max(0,fight.enemy)} / ${fight.enemyMax}`;document.getElementById('enemybar').style.width=(Math.max(0,fight.enemy)/fight.enemyMax*100)+'%';document.getElementById('turnlabel').textContent=`Lượt ${fight.turn} · Đợt ${fight.wave}/${fight.waves}`;document.getElementById('party').innerHTML=save.team.map(id=>{let base=DB.find(x=>x.id===id),c=statsFor(base),hp=Math.max(0,fight.heroHp[id]||0),cd=fight.skillCooldown[id]||0,st=(fight.statuses[id]||[]).map(x=>x.type).join(', ');return `<article class="card">${artHtml(c)}${starsHtml(id)}<h3>${c.name}</h3><p>HP ${hp}/${c.hp}</p><div class="bar"><i style="width:${hp/c.hp*100}%;background:linear-gradient(90deg,#4b9f87,#8edab0)"></i></div><div class="skill-status">${cd>0?'Kỹ năng hồi '+cd+' lượt':'Kỹ năng sẵn sàng'}${st?' · '+st:''}</div></article>`}).join('');let sel=document.getElementById('skillTarget'),old=sel.value;sel.innerHTML=save.team.map(id=>{let c=DB.find(x=>x.id===id);return `<option value="${id}" ${fight.heroHp[id]<=0?'disabled':''}>${c.name} — ${c.skill}${fight.skillCooldown[id]>0?' (hồi '+fight.skillCooldown[id]+')':''}</option>`}).join('');if(save.team.includes(old)&&fight.heroHp[old]>0)sel.value=old;document.getElementById('skillbtn').disabled=fight.ended||!partyAlive().some(id=>(fight.skillCooldown[id]||0)===0);document.getElementById('attackbtn').disabled=fight.ended;document.getElementById('guardbtn').disabled=fight.ended}
function log(msg){let el=document.getElementById('battlelog');el.innerHTML+=`<div>› ${msg}</div>`;el.scrollTop=el.scrollHeight}
function combatFx(kind,text,targetId,critical=false,actorId=null){const layer=document.getElementById('battleVfx'),field=document.querySelector('.battlefield');if(!layer||!field)return;let target=null;if(targetId){const cards=[...document.querySelectorAll('#party .card')];target=cards[save.team.indexOf(targetId)]||null}if(kind==='damage'||kind==='crit'){const el=document.createElement('div');el.className='damage-float '+(kind==='crit'?'crit ':'')+(targetId?'ally-hit':'enemy-hit');el.textContent=text;layer.appendChild(el);el.addEventListener('animationend',()=>el.remove(),{once:true});if(target){target.classList.remove('hit-flash');void target.offsetWidth;target.classList.add('hit-flash')}else{const art=document.getElementById('enemyart');art.classList.remove('hit-flash');void art.offsetWidth;art.classList.add('hit-flash')}if(kind==='crit'||targetId){field.classList.remove('screen-shake');void field.offsetWidth;field.classList.add('screen-shake')}if(actorId){const names={lilith:'✦',satan:'🔥',aya:'🔥',kitsune:'❄',mika:'✚',forneus:'⬡',beelzebub:'◈',lucifer:'⚡',ren:'✧',marbas:'☠',samael:'☄',astaroth:'✧',asmodeus:'♥'};const burst=document.createElement('div');burst.className='skill-burst '+actorId;burst.textContent=names[actorId]||'✦';layer.appendChild(burst);burst.addEventListener('animationend',()=>burst.remove(),{once:true})}}else if(kind==='heal'||kind==='status'){const el=document.createElement('div');el.className='damage-float '+kind+(targetId?' ally-hit':'');el.textContent=text;layer.appendChild(el);el.addEventListener('animationend',()=>el.remove(),{once:true})}}

function startBattle(){if(dungeonMode!=='tower')dungeonMode='tower';resetFight();show('battle')}
function nextDungeonBattle(){if(dungeonMode==='tower'&&fight?.ended&&fight.won&&save.dungeonFloorUnlocked> dungeonFloor){dungeonFloor=Math.min(30,dungeonFloor+1)}resetFight();show('battle')}
function partyAlive(){return save.team.filter(id=>(fight.heroHp[id]||0)>0)}
function rollDamage(raw, chance=.12){let crit=Math.random()<chance;return {dmg:Math.max(1,Math.floor(raw*(crit?1.75:1))),crit}}
function applyEnemyStatus(type,turns){fight.enemyStatuses=fight.enemyStatuses.filter(s=>s.type!==type);fight.enemyStatuses.push({type,turns})}
function recordDamage(id,amount){const d=Math.max(0,Math.floor(amount||0));fight.damageByHero[id]=(fight.damageByHero[id]||0)+d;fight.damageTotal=(fight.damageTotal||0)+d}
function autoBasicAttacks(){let total=0;partyAlive().forEach(id=>{if(fight.enemy<=0)return;let c=statsFor(DB.find(x=>x.id===id)),raw=Math.max(4,c.atk+Math.floor(Math.random()*7)-3-(currentEncounter().def||0)),r=rollDamage(raw,.16);fight.enemy-=r.dmg;recordDamage(id,r.dmg);total+=r.dmg;log(`${c.name} đánh thường ${r.crit?'<b>CHÍ MẠNG</b> ':''}gây ${r.dmg} sát thương.`);combatFx(r.crit?'crit':'damage',(r.crit?'✦ ':'−')+r.dmg,null,r.crit,id);if(c.id==='ren'&&Math.random()<.14){applyEnemyStatus('choáng',1);log('Địch bị choáng!');combatFx('status','✦ CHOÁNG')} });return total}
function attack(){if(!fight||fight.ended)return;if(!partyAlive().length)return endBattle(false);let dmg=autoBasicAttacks();log(`Đội tự động đánh thường tổng cộng ${dmg} sát thương.`);afterPlayer()}
function skill(){if(!fight||fight.ended)return;let id=document.getElementById('skillTarget').value;if(!id||fight.heroHp[id]<=0){log('Hãy chọn một nhân vật còn sống.');return}if((fight.skillCooldown[id]||0)>0){log(`Kỹ năng đang hồi ${fight.skillCooldown[id]} lượt.`);return}let c=statsFor(DB.find(x=>x.id===id)),raw=c.atk*2.15+Math.random()*10-(currentEncounter().def||0),r=rollDamage(raw,.22);fight.enemy-=r.dmg;recordDamage(id,r.dmg);fight.skillCooldown[id]=3;let extra='';if(id==='aya'){applyEnemyStatus('thiêu đốt',2);extra=' · thiêu đốt 2 lượt'}else if(id==='mika'){fight.teamHeal=12;save.team.filter(x=>fight.heroHp[x]>0).forEach(x=>{let cc=statsFor(DB.find(y=>y.id===x));fight.heroHp[x]=Math.min(cc.hp,fight.heroHp[x]+12)});extra=' · hồi 12 HP cho mỗi đồng đội'}else if(id==='kitsune'){applyEnemyStatus('đóng băng',1);extra=' · đóng băng 1 lượt'}else if(id==='marbas'){applyEnemyStatus('độc',3);extra=' · trúng độc 3 lượt'}else if(id==='forneus'){fight.teamShield=1;extra=' · tạo khiên giảm sát thương lượt tới'}else if(id==='beelzebub'){applyEnemyStatus('hư không',2);extra=' · hư không 2 lượt'}log(`${c.name} dùng ${c.skill}, ${r.crit?'CHÍ MẠNG, ':''}gây ${r.dmg} sát thương${extra}.`);combatFx(r.crit?'crit':'damage',(r.crit?'✦ KỸ NĂNG ':'✦ ')+r.dmg,null,r.crit,id);if(id==='mika')combatFx('heal','✚ HỒI MÁU +12');if(['aya','kitsune','marbas','beelzebub'].includes(id))combatFx('status',id==='aya'?'🔥 THIÊU ĐỐT':id==='kitsune'?'❄ ĐÓNG BĂNG':id==='marbas'?'☠ TRÚNG ĐỘC':'◈ HƯ KHÔNG');if(id==='forneus')combatFx('status','🛡 KHIÊN KÍCH HOẠT');afterPlayer()}
function guard(){if(!fight||fight.ended)return;if(!partyAlive().length)return endBattle(false);fight.guard=true;log('Đội vào thế phòng thủ; sát thương phản công giảm mạnh.');enemyTurn()}
function afterPlayer(){renderBattle();if(fight.enemy<=0){if(fight.wave<fight.waves){fight.wave++;fight.turn=1;fight.enemyStatuses=[];let e=currentEncounter();fight.enemy=e.hp;fight.enemyMax=e.hp;fight.bossUsed=false;setEncounterUI();log(`Đợt ${fight.wave} bắt đầu: ${e.name} xuất hiện!`);renderBattle();return}else{endBattle(true);return}}enemyTurn()}
function chooseEnemyTarget(alive){return alive.slice().sort((a,b)=>{let ca=statsFor(DB.find(x=>x.id===a)),cb=statsFor(DB.find(x=>x.id===b));let ra=(fight.heroHp[a]||0)/Math.max(1,ca.hp),rb=(fight.heroHp[b]||0)/Math.max(1,cb.hp);return ra-rb})[0]||alive[0]}
function showEnemyIntent(text){let box=document.getElementById('enemyIntent');if(!box)return;box.textContent=text;box.hidden=!text}
function enemyTurn(){if(fight.ended)return;let e=currentEncounter();let controlSkip=(fight.enemyStatuses||[]).some(s=>s.type==='choáng'||s.type==='đóng băng');let voided=(fight.enemyStatuses||[]).some(s=>s.type==='hư không');if(fight.enemyStatuses?.length){fight.enemyStatuses.forEach(s=>{if(s.type==='thiêu đốt'||s.type==='độc'){let d=s.type==='độc'?12:18;fight.enemy-=d;fight.damageTotal=(fight.damageTotal||0)+d;log(`Địch chịu ${d} sát thương từ ${s.type}.`);combatFx('status',(s.type==='thiêu đốt'?'🔥':'☠')+' −'+d)}else if(s.type==='đóng băng'||s.type==='choáng'){log(`Địch bị ${s.type}, bỏ lượt phản công.`)}else if(s.type==='hư không'){log('Địch bị hư không làm suy yếu: sát thương giảm 25%.')}});fight.enemyStatuses=fight.enemyStatuses.map(s=>({...s,turns:s.turns-1})).filter(s=>s.turns>0);if(fight.enemy<=0){if(fight.wave<fight.waves){afterPlayer();return}else{endBattle(true);return}}}
 let alive=partyAlive();if(!alive.length){endBattle(false);return}
 if(controlSkip){log('Địch mất lượt vì hiệu ứng khống chế.');fight.guard=false;fight.enemyIntent=null;showEnemyIntent('')}
 else if(e.boss&&fight.enemyIntent==='crush'){
   log(`${e.name} tung tuyệt kỹ đã báo trước!`);let targets=partyAlive();targets.forEach(id=>{let c=statsFor(DB.find(x=>x.id===id));let raw=Math.max(6,Math.floor((e.atk||30)*.78)-Math.floor(c.def*.45)+Math.floor(Math.random()*5));let dmg=voided?Math.ceil(raw*.75):raw;if(fight.guard)dmg=Math.ceil(dmg*.35);if(fight.teamShield)dmg=Math.ceil(dmg*.55);fight.heroHp[id]=Math.max(0,(fight.heroHp[id]||0)-dmg);log(`${c.name} nhận ${dmg} sát thương từ tuyệt kỹ boss.`);combatFx('damage','−'+dmg,id)});combatFx('status','☄ TUYỆT KỸ BOSS');if(fight.teamShield)fight.teamShield=0;fight.guard=false;fight.enemyIntent=null;showEnemyIntent('')
 }else{
   let target=chooseEnemyTarget(alive),c=statsFor(DB.find(x=>x.id===target));let bossBonus=e.boss?8:0,baseDmg=Math.max(4,(e.atk||24)+bossBonus-c.def+Math.floor(Math.random()*8)),dmg=voided?Math.ceil(baseDmg*.75):baseDmg;if(fight.guard)dmg=Math.ceil(dmg*.35);if(fight.teamShield){dmg=Math.ceil(dmg*.55);fight.teamShield=0}fight.heroHp[target]=Math.max(0,fight.heroHp[target]-dmg);fight.guard=false;log(`${e.boss?'Boss nhắm vào đồng đội yếu máu! ':'Địch nhắm vào đồng đội yếu máu. '}${c.name} nhận ${dmg} sát thương.`);combatFx('damage','−'+dmg,target)
 }
 Object.keys(fight.skillCooldown).forEach(id=>{if(fight.skillCooldown[id]>0)fight.skillCooldown[id]--});fight.turn++;
 if(e.boss&&!fight.ended&&!fight.enemyIntent&&fight.turn%2===0){fight.enemyIntent='crush';showEnemyIntent(`${e.name} đang tích tụ năng lượng — lượt kế tiếp tung tuyệt kỹ diện rộng! Hãy cân nhắc Phòng thủ.`);log('CẢNH BÁO: Boss đang tích tụ năng lượng cho tuyệt kỹ diện rộng ở lượt kế tiếp!')}
 renderBattle();if(!partyAlive().length)endBattle(false)}
function endBattle(win){stopAuto();fight.won=!!win;fight.ended=true;['attackbtn','skillbtn','guardbtn'].forEach(id=>document.getElementById(id).disabled=true);const rewardBox=document.getElementById('battleReward');if(win){let floor=dungeonMode==='tower'?dungeonFloor:1,e=currentEncounter(),isBoss=dungeonMode==='tower'&&floor%10===0;let rewards={gold:90+floor*25,shards:floor%5===0?3:1,exp:30+floor*12};if(isBoss){rewards.gold=Math.round(rewards.gold*1.65);rewards.shards+=4;rewards.exp=Math.round(rewards.exp*1.5)}save.wins++;save.progress=Math.min(3,Number(save.progress||0)+1);save.gold+=rewards.gold;save.shards+=rewards.shards;save.exp=(save.exp||0)+rewards.exp;save.dungeonWins=(save.dungeonWins||0)+1;let milestone='';if(dungeonMode==='tower'){if(!save.dungeonFloorsCleared.includes(floor))save.dungeonFloorsCleared.push(floor);if(floor>=save.dungeonFloorUnlocked&&floor<30)save.dungeonFloorUnlocked=floor+1;save.dungeonFloorUnlocked=Math.min(30,Math.max(save.dungeonFloorUnlocked,floor));if(isBoss&&!save.bossMilestonesClaimed.includes(floor)){save.bossMilestonesClaimed.push(floor);let bonus={10:{gold:500,shards:8},20:{gold:900,shards:12},30:{gold:1500,shards:20}}[floor];save.gold+=bonus.gold;save.shards+=bonus.shards;milestone=`<p>✦ THƯỞNG LẦN ĐẦU BOSS: +${bonus.gold} vàng · +${bonus.shards} mảnh</p>`}}let levels=Math.floor(save.exp/100);if(levels>0){save.exp%=100;save.level+=levels;log(`Lên ${levels} cấp người chơi!`)}persist();let title=isBoss?'BOSS ĐÃ BỊ ĐÁNH BẠI!':`CHIẾN THẮNG TẦNG ${floor}!`;rewardBox.innerHTML=`<h3>✦ ${title}</h3><p>+${rewards.gold} vàng　·　+${rewards.shards} mảnh　·　+${rewards.exp} EXP</p>${isBoss?'<p>Phần thưởng boss đã tăng cường.</p>':''}${milestone}`;rewardBox.classList.add('show');log(`${title} +${rewards.gold} vàng · +${rewards.shards} mảnh · +${rewards.exp} EXP.${floor<30?' Tầng kế tiếp đã mở nếu đây là tiến độ mới.':' Đã hoàn thành cả 30 tầng!'}`);document.getElementById('nextbtn').hidden=(dungeonMode==='tower'&&floor>=30);renderDungeon()}else{rewardBox.innerHTML='<h3>Đội hình đã bị đánh bại</h3><p>Không mất tài nguyên. Hãy đổi đội hình hoặc nâng cấp rồi thử lại.</p>';rewardBox.classList.add('show');log('Đội hình đã gục ngã. Không mất tài nguyên; hãy đổi đội hình và thử lại.');document.getElementById('nextbtn').hidden=false}const statsBox=document.getElementById('battleStats');const ranked=Object.entries(fight.damageByHero||{}).map(([id,dmg])=>({id,dmg,name:(DB.find(c=>c.id===id)||{name:id}).name})).sort((a,b)=>b.dmg-a.dmg);const top=ranked[0];statsBox.innerHTML=`<h3>📊 Thống kê trận đấu</h3><p>Tổng sát thương đội: <b>${Math.round(fight.damageTotal||0)}</b> · Số lượt: <b>${fight.turn}</b></p><p>${top?`MVP sát thương: <b>${top.name}</b> (${top.dmg})`: 'Chưa ghi nhận sát thương'}</p><div style="text-align:left;margin-top:8px">${ranked.map(x=>`<p style="margin:4px 0">${x.name} <span style="float:right">${x.dmg} (${Math.round(x.dmg/Math.max(1,fight.damageTotal||0)*100)}%)</span></p><div class="bar"><i style="width:${Math.min(100,x.dmg/Math.max(1,top?.dmg||1)*100)}%;background:linear-gradient(90deg,#8c6bd8,#e1b7ff)"></i></div>`).join('')}</div>`;statsBox.classList.add('show');renderBattle();updateHeader()}
function toggleAuto(){autoBattle=!autoBattle;updateAutoButton();if(autoBattle)scheduleAuto();else stopAuto()}
function toggleSpeed(){battleSpeed=battleSpeed===1?2:1;document.getElementById('speedBtn').textContent=`⏩ Tốc độ: ${battleSpeed}×`;if(autoBattle){if(autoTimer)clearTimeout(autoTimer);autoTimer=null;scheduleAuto()}}
function updateAutoButton(){let b=document.getElementById('autoBtn');if(b)b.textContent=autoBattle?'⏸ Tự động: Bật':'▶ Tự động: Tắt'}
function stopAuto(){if(autoTimer)clearTimeout(autoTimer);autoTimer=null;autoBattle=false;updateAutoButton()}
function scheduleAuto(){if(!autoBattle||!fight||fight.ended)return;autoTimer=setTimeout(()=>{if(!autoBattle||!fight||fight.ended)return;let id=save.team.find(x=>fight.heroHp[x]>0&&(fight.skillCooldown[x]||0)===0);if(id){document.getElementById('skillTarget').value=id;skill()}else attack();if(autoBattle&&!fight.ended)scheduleAuto()},battleSpeed===2?450:900)}
function resetGame(){if(confirm('Xóa toàn bộ tiến trình Devil Rocker trên trình duyệt này?')){localStorage.removeItem('dmt_offline_save');save={...defaults,team:[...defaults.team],owned:[...defaults.owned]};persist();show('home')}}


function debugAmounts(){const g=Number(document.getElementById('debugGold')?.value),sh=Number(document.getElementById('debugShards')?.value);if(!Number.isFinite(g)||!Number.isFinite(sh)||g<0||sh<0||!Number.isInteger(g)||!Number.isInteger(sh)){alert('Nhập số nguyên không âm cho vàng và mảnh.');return null}return {g,sh}}
function debugAddResources(gold,shards){if(gold===undefined){const a=debugAmounts();if(!a)return;gold=a.g;shards=a.sh}save.gold=Math.max(0,Number(save.gold)||0)+gold;save.shards=Math.max(0,Number(save.shards)||0)+shards;persist();const el=document.getElementById('debugStatus');if(el)el.textContent=`Đã cộng ${gold.toLocaleString()} vàng và ${shards.toLocaleString()} mảnh. Số dư: ${save.gold.toLocaleString()} vàng · ${save.shards.toLocaleString()} mảnh.`}
function debugSetResources(){const a=debugAmounts();if(!a)return;save.gold=a.g;save.shards=a.sh;persist();document.getElementById('debugStatus').textContent=`Đã đặt số dư: ${save.gold.toLocaleString()} vàng · ${save.shards.toLocaleString()} mảnh.`}
function debugUnlockAll(){DB.forEach(c=>{if(!save.owned.includes(c.id))save.owned.push(c.id)});persist();document.getElementById('debugStatus').textContent=`Đã mở ${DB.length} thẻ. Đội hình hiện tại được giữ nguyên.`;alert('Đã mở toàn bộ thẻ Devil!')}
function debugMaxPower(){save.owned.forEach(id=>{save.cardLevels[id]=Math.max(99,Number(save.cardLevels[id]||1));save.cardStars[id]=6;save.dupes[id]=Math.max(99,Number(save.dupes[id]||0))});save.level=99;persist();if(document.getElementById('debugStatus'))document.getElementById('debugStatus').textContent='Đã đặt toàn bộ thẻ sở hữu lên Lv.99, 6★ và người chơi Lv.99.';if(document.getElementById('team').classList.contains('active'))renderTeam();if(document.getElementById('cards').classList.contains('active'))renderCollection();if(document.getElementById('upgrade').classList.contains('active'))renderUpgrade();if(document.getElementById('ascend').classList.contains('active'))renderAscend();updateHeader();alert('Đã tăng sức mạnh thẻ sở hữu để test!')}
function debugUnlockDungeon(){save.dungeonFloorUnlocked=30;save.dungeonFloorsCleared=Array.from({length:30},(_,i)=>i+1);persist();if(document.getElementById('dungeon').classList.contains('active'))renderDungeon();document.getElementById('debugStatus').textContent='Đã mở và đánh dấu hoàn thành 30 tầng Dungeon.';alert('Đã mở 30 tầng Dungeon!')}

let ssrRevealQueue=[];
function detailCardParallax(ev,el){if(ev.pointerType==='touch'||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=el.getBoundingClientRect();if(!r.width||!r.height)return;const x=(ev.clientX-r.left)/r.width,y=(ev.clientY-r.top)/r.height;el.style.setProperty('--tilt-x',((.5-y)*7).toFixed(2)+'deg');el.style.setProperty('--tilt-y',((x-.5)*9).toFixed(2)+'deg');el.style.filter=`brightness(${1.02+Math.abs(x-.5)*.12})`;}
function resetDetailCardParallax(el){el.style.setProperty('--tilt-x','0deg');el.style.setProperty('--tilt-y','0deg');el.style.filter='';}
function showSSRReveal(ids){ssrRevealQueue=ids.map(id=>DB.find(c=>c.id===id)).filter(Boolean);if(!ssrRevealQueue.length)return;document.getElementById('ssrRevealOverlay').classList.add('open');nextSSRReveal(true);}
function nextSSRReveal(first=false){const overlay=document.getElementById('ssrRevealOverlay');if(!ssrRevealQueue.length){overlay.classList.remove('open');/* Rebuild the complete roll list after the spotlight sequence so every pulled card, including each SSR copy, is present in the final lineup. */renderGacha(true);const results=document.getElementById('gachaResults');if(results){results.classList.add('gacha-results-highlight');requestAnimationFrame(()=>results.scrollIntoView({behavior:'smooth',block:'center'}));}return;}const c=ssrRevealQueue.shift(),holder=document.getElementById('ssrRevealCard');holder.innerHTML=artHtml(c,'ssr-spotlight',true);document.getElementById('ssrRevealName').textContent=c.name;document.getElementById('ssrRevealDesc').textContent='SSR · ★'+cardStars(c.id)+' · '+c.desc;const btn=document.getElementById('ssrRevealNext');btn.textContent=ssrRevealQueue.length?'SSR tiếp theo ('+ssrRevealQueue.length+')':'Xem toàn bộ kết quả';holder.style.animation='none';void holder.offsetWidth;holder.style.animation='';}
function pullGacha(n,fast=false){const cost=n===1?3:12;if(save.shards<cost){alert('Không đủ mảnh triệu hồi. Cần '+cost+' mảnh.');return}save.shards-=cost;lastGacha=[];let fresh=0,dupeCount=0,bonusShards=0;for(let i=0;i<n;i++){let c; if(!save.owned.includes('aya')&&(save.gachaPulls||0)===0&&i===0){c=DB.find(x=>x.id==='aya');}else{const roll=Math.random();let rarity=roll<.01?'SSR':roll<.20?'SR':'R';const pool=DB.filter(x=>x.rarity===rarity);c=(rarity==='SSR'&&Math.random()<.45?DB.find(x=>x.id==='aya'):pool[Math.floor(Math.random()*pool.length)])||DB[0];}lastGacha.push(c.id);if(!save.owned.includes(c.id)){save.owned.push(c.id);fresh++}else{dupeCount++;const reward=c.rarity==='SSR'?10:c.rarity==='SR'?5:2;save.shards+=reward;bonusShards+=reward;save.dupes[c.id]=(save.dupes[c.id]||0)+1;}}save.gachaPulls=(save.gachaPulls||0)+n;persist();renderGacha(fast);const summary=document.getElementById('gachaSummary');if(summary)summary.textContent=`${fast?'Quay nhanh':'Triệu hồi'} ${n} lượt: ${fresh} thẻ mới · ${dupeCount} thẻ trùng · +${bonusShards} mảnh từ thẻ trùng. Tỷ lệ: SSR 1% · SR 19% · R 80%. Lượt triệu hồi đầu tiên bảo đảm Lilith nếu bạn chưa sở hữu cô ấy; sau đó Lilith là Devil nổi bật trong nhóm SSR.`;if(!fast){const el=document.getElementById('gachaResults');el.classList.remove('gacha-reveal','gacha-results-highlight');void el.offsetWidth;el.classList.add('gacha-reveal');}const ssrs=lastGacha.filter(id=>{const c=DB.find(x=>x.id===id);return c&&c.rarity==='SSR'});if(ssrs.length)showSSRReveal(ssrs); }
function renderGacha(fast=false){const el=document.getElementById('gachaResults');if(!el)return;document.getElementById('gachaCount').textContent=(save.gachaPulls||0)+' lượt';el.innerHTML=lastGacha.length?lastGacha.map((id,i)=>{const c=DB.find(x=>x.id===id);const isNew=lastGacha.slice(0,i).indexOf(id)<0;return `<article class="card gacha-card ${fast?'fast':''} ${c.rarity==='SSR'?'gacha-ssr':''}" style="--delay:${fast?0:i*90}ms"><div>${artHtml(c,'',true)}${starsHtml(c.id)}<div class="rarity ${c.rarity}">${c.rarity} · ★${cardStars(c.id)}</div><h3>${c.name}</h3><p>${isNew&&!lastGacha.slice(0,i).includes(id)?'Kết quả triệu hồi':'Có thể là thẻ trùng'} · ${c.rarity==='SSR'?'+10':c.rarity==='SR'?'+5':'+2'} mảnh nếu trùng</p></div></article>`}).join(''):'<div class="panel muted">Chưa có lượt triệu hồi trong phiên này.</div>'; }
function enterDungeon(mode='tower',floor=1){dungeonMode='tower';dungeonFloor=Math.max(1,Math.min(Number(floor)||1,save.dungeonFloorUnlocked));resetFight();show('battle');document.getElementById('dungeonInfo').textContent=`Đang vào tầng ${dungeonFloor}/30. Cần chiến thắng để mở khóa tầng kế tiếp.`;}
function renderDungeon(){const el=document.getElementById('dungeonFloors');if(!el)return;document.getElementById('dungeonProgress').textContent=`Đã mở ${save.dungeonFloorUnlocked}/30 tầng · Đã vượt ${save.dungeonFloorsCleared.length}/30`;el.innerHTML=Array.from({length:30},(_,i)=>{const f=i+1,area=Math.floor((f-1)/10)+1,local=((f-1)%10)+1,locked=f>save.dungeonFloorUnlocked,cleared=save.dungeonFloorsCleared.includes(f),boss=f%10===0,areaNames=['Shinjuku Đổ Nát','Linh Giới Vỡ Nứt','Điện Quỷ Vương'];return `${local===1?`<div class="panel" style="grid-column:1/-1"><h3>Khu vực ${area}: ${areaNames[area-1]}</h3><p class="muted">Tầng ${((area-1)*10)+1}–${area*10} · ${boss?'Boss cuối khu vực':''}</p></div>`:''}<article class="card floor-card ${locked?'locked':''} ${boss?'boss-floor':''}"><div><div class="art">${locked?'🔒':cleared?'🏆':boss?'🐉':'🌑'}</div><div class="rarity ${boss?'SSR':'R'}">${locked?'CHƯA MỞ':cleared?'ĐÃ VƯỢT':boss?'BOSS FLOOR':'DUNGEON'}</div><h3>Tầng ${f} · ${boss?'Thủ lĩnh':`Khu vực ${local}`}</h3><p>${locked?'Thắng tầng trước để mở khóa':cleared?'Có thể chơi lại':'Địch tăng sức mạnh theo tầng'}<br>Thưởng: ${f%10===0?Math.round((90+f*25)*1.65):90+f*25} vàng · ${f%10===0?(f%5===0?7:5):(f%5===0?3:1)} mảnh${boss?'<br><b style="color:#ff9eae">Boss + thưởng mốc lần đầu</b>':''}</p></div><button ${locked?'disabled':''} class="${f===save.dungeonFloorUnlocked?'primary':''}" onclick="enterDungeon('tower',${f})">${locked?'Đang khóa':cleared?'Chơi lại':'Vào tầng'}</button></article>`}).join('');}
let ascId='aya';
function renderAscend(){
 const el=document.getElementById('ascPicker'); if(!el)return;
 el.innerHTML=DB.filter(c=>save.owned.includes(c.id)).map(c=>`<button class="${c.id===ascId?'primary':''}" onclick="ascId='${c.id}';renderAscend()">${c.art} ${c.name} · ★${cardStars(c.id)}</button>`).join('');
 const c=DB.find(x=>x.id===ascId)||DB[0],stars=cardStars(c.id),need=stars*(c.rarity==='SSR'?10:c.rarity==='SR'?6:3);
 document.getElementById('ascSelectedName').textContent=c.name;
 const prefix=STAR_ART_PREFIX[c.id],nextImage=prefix?`${prefix}_${stars+1}star.webp`:`${c.image||c.id+'.webp'}`;document.getElementById('ascPreview').innerHTML=`${artHtml(c,'asc-art')}<div class="asc-caption"><b>★ ${stars}/6 · ${stars===6?'Thức tỉnh tối đa':'Tiến hóa '+stars+'/6'}</b>${stars<6?`Khi thăng lên ★${stars+1}, game sẽ ưu tiên ảnh ${nextImage}.`:'Đã đạt hình thái tối thượng.'}<p>Ảnh tự đổi ngay sau khi nâng sao nếu đã có file tương ứng.</p></div>`;
 document.getElementById('ascDetail').innerHTML=`${starsHtml(c.id)}<p>${c.rarity} · ★${stars}/6<br>Mảnh cần: <b>${need}</b> · Hiện có: <b>${save.shards||0}</b><br>Mỗi sao: +8% ATK, +8% HP, +5% DEF. Lilith, Astaroth và Asmodeus thay ảnh theo từng cấp sao nếu file tương ứng có trong assets/cards/.</p>`;
}
function ascendSelected(){
 const c=DB.find(x=>x.id===ascId); if(!c)return;
 const stars=cardStars(c.id),need=stars*(c.rarity==='SSR'?10:c.rarity==='SR'?6:3);
 if(stars>=6){alert('Thẻ đã đạt tối đa 6 sao.');return}
 if((save.shards||0)<need){alert(`Chưa đủ mảnh. Thăng lên ★${stars+1} cần ${need} mảnh.`);return}
 save.shards-=need;save.cardStars[c.id]=stars+1;persist();renderAscend();renderCollection();renderTeam();renderUpgrade();if(fight&&!fight.ended)renderBattle();updateHeader();
 alert(`${c.name} đã thăng lên ★${stars+1}! Ảnh tiến hóa được cập nhật nếu đã có file tương ứng.`);
}
function ascendMaxSelected(){
 const c=DB.find(x=>x.id===ascId); if(!c)return;
 let upgraded=0,totalCost=0;
 while((save.cardStars[c.id]||1)<6){const stars=save.cardStars[c.id]||1;const need=stars*(c.rarity==='SSR'?10:c.rarity==='SR'?6:3);if((save.shards||0)<need)break;save.shards-=need;save.cardStars[c.id]=stars+1;upgraded++;totalCost+=need;}
 if(!upgraded){alert((cardStars(c.id)>=6)?'Thẻ đã đạt tối đa 6 sao.':'Không đủ mảnh để nâng thêm sao.');return;}
 persist();renderAscend();renderCollection();renderTeam();renderUpgrade();if(fight&&!fight.ended)renderBattle();updateHeader();alert(`${c.name} đã nâng ${upgraded} cấp sao, dùng ${totalCost} mảnh. Hiện tại ★${cardStars(c.id)}/6.`);
}
function renderUpgrade(){let el=document.getElementById('upgradeCards');if(!el)return;el.innerHTML=DB.filter(c=>save.owned.includes(c.id)).map(c=>{let lv=cardLevel(c.id),cost=lv*100;return cardHtml(c,`Nâng cấp · ${cost} vàng`,`upgradeCard('${c.id}')`)+''}).join('');}
function upgradeCard(id){let lv=cardLevel(id),cost=lv*100;if(save.gold<cost){alert('Không đủ vàng.');return}save.gold-=cost;save.cardLevels[id]=lv+1;persist();renderUpgrade();alert('Nâng cấp thành công: Lv.'+(lv+1));}
function renderQuests(){let el=document.getElementById('questCards');if(!el)return;let quests=[{id:'first',name:'Tân binh Tokyo',desc:'Thắng 1 trận',ok:save.wins>=1,reward:100},{id:'five',name:'Thợ săn ác linh',desc:'Thắng 5 trận',ok:save.wins>=5,reward:250},{id:'dungeon',name:'Thám hiểm cổng',desc:'Vượt 3 dungeon',ok:(save.dungeonWins||0)>=3,reward:5,shards:true},{id:'summon',name:'Khế ước đầu tiên',desc:'Triệu hồi 1 lần',ok:(save.gachaPulls||0)>=1,reward:120}];el.innerHTML=quests.map(q=>{let claimed=(save.claimed||[]).includes(q.id);return `<article class="card"><div><div class="art">${q.ok?'🏆':'📜'}</div><div class="rarity">${q.ok?'HOÀN THÀNH':'NHIỆM VỤ'}</div><h3>${q.name}</h3><p>${q.desc}<br>Thưởng: ${q.shards?q.reward+' mảnh':q.reward+' vàng'}</p></div><button ${(!q.ok||claimed)?'disabled':''} onclick="claimQuest('${q.id}',${q.reward},${!!q.shards})">${claimed?'Đã nhận':q.ok?'Nhận thưởng':'Chưa hoàn thành'}</button></article>`}).join('');}
function claimQuest(id,reward,shards){save.claimed=save.claimed||[];if(save.claimed.includes(id))return;save.claimed.push(id);if(shards)save.shards+=reward;else save.gold+=reward;persist();renderQuests();}

updateHeader();
if(!localStorage.getItem('dmt_tutorial_seen_v1'))openTutorial(false);
